import{_ as s}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Claude Code 术语表 / Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/claude/claude-code-glossary.md","filePath":"zh/products/ai-coding/claude/claude-code-glossary.md","lastUpdated":1787044708000}'),d={name:"zh/products/ai-coding/claude/claude-code-glossary.md"};function n(r,t,l,i,p,h){return a(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="claude-code-术语表-glossary" tabindex="-1">Claude Code 术语表 / Glossary <a class="header-anchor" href="#claude-code-术语表-glossary" aria-label="Permalink to &quot;Claude Code 术语表 / Glossary&quot;">​</a></h1><blockquote><p>这是一份<strong>解释型</strong>文档——回答&quot;这个概念是什么、为什么这样设计、什么时候该用&quot;。和 <a href="./claude-code-cheatsheet.html">Claude Code Cheatsheet</a> 互补：cheatsheet 回答&quot;怎么配置、参数是什么、怎么选&quot;，本文档回答&quot;这是什么、为什么需要、它怎么和其他概念打交道&quot;。</p><p><strong>所有跨章节共享的术语</strong>都在这里统一定义，主教程 <a href="./claude-code.html">Claude Code</a> 和 <a href="./claude-code-cookbook.html">实战 Cookbook</a> 引用这里，不重复解释，避免口径不一致。</p></blockquote><h2 id="概念关系图" tabindex="-1">概念关系图 <a class="header-anchor" href="#概念关系图" aria-label="Permalink to &quot;概念关系图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌─────────────┐</span></span>
<span class="line"><span>                    │   MCP 协议   │  ← 最底层开放协议</span></span>
<span class="line"><span>                    │ (开放标准)   │</span></span>
<span class="line"><span>                    └──────┬──────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>              ┌────────────┼────────────┐</span></span>
<span class="line"><span>              │            │            │</span></span>
<span class="line"><span>         ┌────┴────┐  ┌───┴───┐  ┌────┴────┐</span></span>
<span class="line"><span>         │ Hooks   │  │Skills │  │Connectors│  ← 基于 MCP 的不同封装</span></span>
<span class="line"><span>         │ (钩子)  │  │(技能) │  │(连接器)  │</span></span>
<span class="line"><span>         └────┬────┘  └───┬───┘  └──────────┘</span></span>
<span class="line"><span>              │           │</span></span>
<span class="line"><span>              └─────┬─────┘</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>              ┌─────┴─────┐</span></span>
<span class="line"><span>              │  Plugins  │  ← 打包以上能力为可安装单元</span></span>
<span class="line"><span>              │  (插件)   │</span></span>
<span class="line"><span>              └───────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>外部协作           ┌─────────────┐  ┌─────────────┐</span></span>
<span class="line"><span>                 │ Sub-agents  │  │  Memory     │</span></span>
<span class="line"><span>                 │ (子代理)    │  │ (记忆)      │</span></span>
<span class="line"><span>                 └─────────────┘  └─────────────┘</span></span></code></pre></div><p><strong>核心逻辑</strong>：MCP 是最底层的开放协议，定义了 Claude 如何与外部工具通信。Hooks、Skills、Connectors 都是基于 MCP 的不同封装层次。Plugins 把 Skills + Agents + Hooks + MCP 打包成一个可安装的单元。Sub-agents 和 Memory 平行于上述主线，是关于&quot;多代理协作&quot;和&quot;跨会话记忆&quot;的独立维度。</p><hr><h2 id="mcp-model-context-protocol" tabindex="-1">MCP（Model Context Protocol） <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP（Model Context Protocol）&quot;">​</a></h2><p><strong>是什么</strong>：一个开放标准协议，定义 AI 应用（如 Claude）如何与外部工具、数据库和 API 安全通信。可以理解为 AI 世界的&quot;USB 接口&quot;——遵循协议的工具有一个就能插一个。</p><p><strong>为什么重要</strong>：没有 MCP 之前，每个 AI 工具都需要自己实现一套连接外部服务的逻辑，连接 GitHub、数据库、Slack 都要单独写。有了 MCP 后：</p><ul><li><strong>工具开发者</strong>只需实现一次 MCP 服务器，所有支持 MCP 的 AI 都能使用</li><li><strong>用户</strong>只需配置一次连接，就可以在 Claude Code、Claude.ai、Claude Desktop 之间共享</li><li><strong>生态</strong>：GitHub、数据库、Slack、Jira 等 1000+ 工具已有 MCP 服务器实现</li></ul><p><strong>在 Claude 生态中的角色</strong>：</p><table tabindex="0"><thead><tr><th>层面</th><th>基于 MCP 的能力</th><th>说明</th></tr></thead><tbody><tr><td>Claude Code CLI</td><td><code>claude mcp add</code> 添加 MCP 服务器</td><td>本地进程或 HTTP 服务器</td></tr><tr><td>Claude.ai / Desktop</td><td>Connectors 连接器</td><td>云端 MCP 服务器，一键 OAuth 授权</td></tr><tr><td>Plugins</td><td><code>.mcp.json</code> 配置</td><td>插件内嵌的 MCP 服务器定义</td></tr><tr><td>Custom Tools</td><td>自定义 MCP 服务器</td><td>接入内网或自建工具</td></tr></tbody></table><p><strong>两种传输方式</strong>：</p><table tabindex="0"><thead><tr><th>方式</th><th>适用场景</th><th>配置示例</th></tr></thead><tbody><tr><td><strong>stdio</strong></td><td>本地进程（数据库、命令行工具）</td><td><code>claude mcp add --transport stdio db -- npx -y @bytebase/dbhub</code></td></tr><tr><td><strong>HTTP/SSE</strong></td><td>远程服务（云端 API、内网服务）</td><td><code>claude mcp add --transport http github https://api.github.com/mcp/</code></td></tr></tbody></table><p><strong>官方文档</strong>：</p><ul><li><a href="https://code.claude.com/docs/zh-CN/build-with-claude/mcp" target="_blank" rel="noreferrer">MCP 开发指南</a></li><li><a href="https://api.anthropic.com/mcp-registry" target="_blank" rel="noreferrer">MCP 注册表</a></li><li><a href="https://code.claude.com/docs/zh-CN/cli-reference#mcp" target="_blank" rel="noreferrer">Claude Code MCP 参考</a></li></ul><hr><h2 id="skills-技能" tabindex="-1">Skills（技能） <a class="header-anchor" href="#skills-技能" aria-label="Permalink to &quot;Skills（技能）&quot;">​</a></h2><p><strong>是什么</strong>：包含指令、脚本和资源的文件夹，Claude 动态加载来提升专项任务的稳定性。简单说：技能让 Claude 在特定任务上更专业、更稳定。</p><p><strong>两种 Skills</strong>：</p><table tabindex="0"><thead><tr><th>类型</th><th>位置</th><th>说明</th></tr></thead><tbody><tr><td><strong>Project Skills</strong></td><td><code>.claude/skills/&lt;name&gt;/SKILL.md</code></td><td>项目共享，提交到 Git</td></tr><tr><td><strong>User Skills</strong></td><td><code>~/.claude/skills/&lt;name&gt;/SKILL.md</code></td><td>个人全局，所有项目生效</td></tr></tbody></table><p><strong>核心机制</strong>：</p><ol><li>Claude 在对话中分析当前任务</li><li>匹配 Skills 目录中的 <code>description</code> 字段</li><li>命中后自动加载对应的 <code>SKILL.md</code> 指令</li><li>也可以手动用 <code>/skill-name</code> 调用</li></ol><p><strong>与 Commands 的区别</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>Commands（命令）</th><th>Skills（技能）</th></tr></thead><tbody><tr><td>触发方式</td><td>手动 <code>/command</code></td><td>自动识别 + 手动</td></tr><tr><td>结构</td><td>单个 <code>.md</code> 文件</td><td>带资源的目录（<code>SKILL.md</code> + 脚本）</td></tr><tr><td>复杂度</td><td>简单提示词</td><td>多文件、多步骤工作流</td></tr></tbody></table><p><strong>SKILL.md 示例</strong>：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">code-reviewer</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">当用户要求代码审查、PR 审查、或检查代码质量时使用</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tools</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Read, Grep, Glob</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">你是一位资深代码审查专家。请检查以下方面：</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 安全漏洞（OWASP Top 10）</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 性能问题</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 代码风格一致性</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">4.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 测试覆盖率</span></span></code></pre></div><p><strong>官方文档</strong>：</p><ul><li><a href="https://code.claude.com/docs/zh-CN/skills" target="_blank" rel="noreferrer">Skills 开发指南</a></li><li><a href="https://support.claude.com/zh-CN/articles/12512198" target="_blank" rel="noreferrer">Claude.ai Skills</a></li></ul><hr><h2 id="hooks-钩子" tabindex="-1">Hooks（钩子） <a class="header-anchor" href="#hooks-钩子" aria-label="Permalink to &quot;Hooks（钩子）&quot;">​</a></h2><p><strong>是什么</strong>：在 Claude Code 工具调用前后<strong>自动触发</strong>的脚本，用于实现自动化工作流。比如：保存文件后自动格式化、提交前跑 lint、会话开始时加载环境变量。</p><p><strong>为什么需要 Hook</strong>：Skills 是 Claude 根据场景<strong>判断</strong>要不要加载（语义匹配），Hooks 是在特定事件<strong>必定</strong>触发（确定性，比如&quot;每次保存都跑格式&quot;），两者互补。</p><p><strong>常见触发事件</strong>：</p><table tabindex="0"><thead><tr><th>事件</th><th>触发时机</th><th>典型用途</th></tr></thead><tbody><tr><td><code>PreToolUse</code></td><td>工具调用前</td><td>拦截危险操作、修改参数</td></tr><tr><td><code>PostToolUse</code></td><td>工具调用后</td><td>自动格式化、lint、测试</td></tr><tr><td><code>SessionStart</code></td><td>会话开始</td><td>加载环境变量、初始化</td></tr><tr><td><code>SessionEnd</code></td><td>会话结束</td><td>清理、报告</td></tr><tr><td><code>UserPromptSubmit</code></td><td>用户提交消息</td><td>日志、验证</td></tr><tr><td><code>ConfigChange</code></td><td>配置文件变更</td><td>重载自定义配置</td></tr></tbody></table><blockquote><p>完整事件清单和 <code>if</code> 条件语法，见 <a href="https://code.claude.com/docs/zh-CN/hooks-reference" target="_blank" rel="noreferrer">Hooks 参考</a> 和 <a href="./claude-code-cheatsheet.html#hook-配置">cheatsheet · Hook 配置</a>。</p></blockquote><p><strong>三种 Hook 类型</strong>：</p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th><th>适用场景</th></tr></thead><tbody><tr><td><code>command</code></td><td>执行 shell 命令</td><td>格式化、lint、测试</td></tr><tr><td><code>prompt</code></td><td>注入额外的 prompt 给 Claude</td><td>动态注入上下文</td></tr><tr><td><code>mcp_tool</code></td><td>调用 MCP 服务器</td><td>复杂外部集成</td></tr></tbody></table><p><strong>官方文档</strong>：</p><ul><li><a href="https://code.claude.com/docs/zh-CN/hooks-guide" target="_blank" rel="noreferrer">Hooks 开发指南</a></li><li><a href="https://code.claude.com/docs/zh-CN/hooks-reference" target="_blank" rel="noreferrer">Hooks 参考</a></li></ul><hr><h2 id="plugins-插件" tabindex="-1">Plugins（插件） <a class="header-anchor" href="#plugins-插件" aria-label="Permalink to &quot;Plugins（插件）&quot;">​</a></h2><p><strong>是什么</strong>：扩展 Claude Code 能力的<strong>独立单元</strong>，可以打包 Skills、Agents、Hooks、MCP 服务器等功能，实现跨项目复用和团队共享。一个插件本质上是一个<strong>目录</strong>，里面包含若干组件。</p><p><strong>插件与组件的关系</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Plugin（插件）</span></span>
<span class="line"><span>├── skills/        ← Skills 技能</span></span>
<span class="line"><span>├── agents/        ← Sub-agents 子代理</span></span>
<span class="line"><span>├── hooks/         ← Hooks 钩子</span></span>
<span class="line"><span>├── .mcp.json      ← MCP 服务器</span></span>
<span class="line"><span>├── .lsp.json      ← LSP 服务器</span></span>
<span class="line"><span>└── settings.json  ← 默认配置</span></span></code></pre></div><p><strong>插件 vs 技能</strong>：插件是&quot;打包好的能力包&quot;，技能是其中的一个组件。你可以只用技能（直接复制到 <code>.claude/skills/</code>），也可以把多个技能打包成插件发布（npm / Git / Marketplace）。</p><p><strong>两种安装范围</strong>：</p><table tabindex="0"><thead><tr><th>范围</th><th>存储位置</th><th>说明</th></tr></thead><tbody><tr><td><code>--scope user</code></td><td><code>~/.claude/plugins/cache/</code></td><td>用户级，所有项目生效（默认）</td></tr><tr><td><code>--scope project</code></td><td><code>.claude/</code></td><td>仅当前项目生效（提交到 Git 可团队共享）</td></tr></tbody></table><p><strong>插件来源</strong>：</p><table tabindex="0"><thead><tr><th>来源</th><th>说明</th></tr></thead><tbody><tr><td><strong>npm</strong></td><td><code>claude plugin install @company/ai-kit</code></td></tr><tr><td><strong>Git</strong></td><td>从 GitHub/GitLab 仓库安装</td></tr><tr><td><strong>本地目录</strong></td><td><code>claude --plugin-dir ./my-plugin</code></td></tr></tbody></table><p><strong>官方文档</strong>：</p><ul><li><a href="https://code.claude.com/docs/zh-CN/plugins-reference" target="_blank" rel="noreferrer">Plugins 参考</a></li><li><a href="https://code.claude.com/docs/zh-CN/plugin-marketplaces" target="_blank" rel="noreferrer">Marketplace</a></li><li><a href="https://code.claude.com/docs/zh-CN/plugins" target="_blank" rel="noreferrer">Claude Code Plugins</a></li></ul><hr><h2 id="sub-agents-子代理" tabindex="-1">Sub-agents（子代理） <a class="header-anchor" href="#sub-agents-子代理" aria-label="Permalink to &quot;Sub-agents（子代理）&quot;">​</a></h2><p><strong>是什么</strong>：拥有<strong>独立人格、权限和工具集</strong>的 AI 助手。主代理可以生成多个子代理并行处理不同任务，然后合并结果。</p><p><strong>为什么需要</strong>：复杂任务里，一个 Agent 处理会&quot;上下文污染&quot;——长对话里既有探索、又有实现、又有审查，思路互相干扰。Sub-agents 给每个子任务一个<strong>独立干净的上下文窗口</strong>。</p><p><strong>两种子代理</strong>：</p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th><th>配置位置</th></tr></thead><tbody><tr><td><strong>内置</strong></td><td>Explore（代码库探索）、Plan（规划调研）</td><td>系统内置，无需配置</td></tr><tr><td><strong>自定义</strong></td><td>你定义的专项代理</td><td><code>.claude/agents/&lt;name&gt;.md</code></td></tr></tbody></table><p><strong>自定义子代理示例</strong>：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- .claude/agents/security-reviewer.md --&gt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: security-reviewer</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: 当需要安全审查、检查权限漏洞或 OWASP 合规时调用</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tools: Read, Grep, Glob</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model: claude-opus-4-6</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">permissionMode: ask</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">你是一位专注于 Web 安全的代码审查专家，擅长识别 OWASP Top 10 漏洞。</span></span></code></pre></div><p><strong>适用场景</strong>：</p><ul><li>大型任务拆分：让多个代理并行审查不同模块</li><li>专业化分工：安全审查、性能分析、测试生成各用一个代理</li><li>模型选择：简单任务用 Sonnet，复杂任务用 Opus</li><li><strong>上下文隔离</strong>：避免长任务污染主对话上下文</li></ul><p><strong>关键约束</strong>：</p><ul><li><strong>无子代理嵌套</strong>：子代理不能再委托子代理</li><li><strong>上下文隔离</strong>：每个子代理有独立的上下文窗口，不会看到主代理或其他子代理的对话</li><li><strong>并行执行</strong>：多个子代理可同时运行，独立消耗各自模型的配额</li></ul><p><strong>官方文档</strong>：<a href="https://code.claude.com/docs/zh-CN/sub-agents" target="_blank" rel="noreferrer">Sub-agents 指南</a></p><hr><h2 id="memory-记忆" tabindex="-1">Memory（记忆） <a class="header-anchor" href="#memory-记忆" aria-label="Permalink to &quot;Memory（记忆）&quot;">​</a></h2><p><strong>是什么</strong>：让 Claude 能<strong>跨对话记住</strong>你的偏好、背景信息和工作习惯，不再每次都要重新介绍自己。</p><p><strong>两种互补记忆</strong>：</p><table tabindex="0"><thead><tr><th>机制</th><th>谁写</th><th>目的</th><th>存储位置</th></tr></thead><tbody><tr><td><strong>CLAUDE.md</strong></td><td>你手动编写</td><td>项目规范、技术栈、编码约定</td><td><code>.claude/CLAUDE.md</code>（提交到 Git）</td></tr><tr><td><strong>自动记忆（Auto Memory）</strong></td><td>Claude 自动写入</td><td>构建命令、调试发现、架构决策</td><td><code>~/.claude/projects/&lt;project&gt;/memory/</code></td></tr></tbody></table><p><strong>为什么需要两套</strong>：CLAUDE.md 解决&quot;你告诉 Claude&quot;的稳定规则（团队/项目规范）；自动记忆解决&quot;Claude 自己学到&quot;的动态知识（&quot;昨天调试发现这个 API 在测试环境返回 500&quot;）。前者是规范，后者是个人笔记。</p><p><strong>CLAUDE.md 加载层级</strong>（具体规则与作用域全表见 <a href="./claude-code-cheatsheet.html#配置作用域速查">cheatsheet · Settings Scope</a>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Managed policy（企业/系统，最高优先级）</span></span>
<span class="line"><span>    └── ~/.claude/CLAUDE.md（用户全局）</span></span>
<span class="line"><span>        └── .claude/CLAUDE.md（项目共享，提交到 Git）</span></span>
<span class="line"><span>            └── .claude/CLAUDE.local.md（个人本地覆盖，不提交）</span></span></code></pre></div><p><strong>自动记忆的索引机制</strong>：</p><ul><li><strong>索引文件</strong>：<code>MEMORY.md</code>——启动时自动加载前 200 行（约 25KB）</li><li><strong>每条记忆</strong>：独立 <code>.md</code> 文件，包含 frontmatter（名称、描述、类型、时间戳）</li><li><strong>记忆类型</strong>：用户偏好（user）、反馈（feedback）、项目知识（project）、外部参考（reference）</li><li><strong>自动关联</strong>：记忆间通过 <code>[[记忆名称]]</code> 互相链接</li></ul><p><strong>官方文档</strong>：<a href="https://code.claude.com/docs/zh-CN/memory" target="_blank" rel="noreferrer">Memory 系统</a></p><hr><h2 id="dynamic-workflows-动态工作流" tabindex="-1">Dynamic Workflows（动态工作流） <a class="header-anchor" href="#dynamic-workflows-动态工作流" aria-label="Permalink to &quot;Dynamic Workflows（动态工作流）&quot;">​</a></h2><p><strong>是什么</strong>：通过 JavaScript 脚本编排大规模子代理工作流的能力。Claude 负责编写脚本，运行时负责执行——将多 Agent 协作从&quot;手动调度&quot;升级为&quot;脚本化流水线&quot;。</p><p><strong>为什么需要</strong>：Sub-agents 适合&quot;主代理手动调起几个子代理&quot;的中等场景；如果要做<strong>大规模并行</strong>（如同时审查 100 个 PR）或<strong>可复用流水线</strong>（构建→测试→部署），用脚本编排比逐个手动调度更可维护。</p><p><strong>核心 API</strong>：</p><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>模式</th></tr></thead><tbody><tr><td><code>agent()</code></td><td>并行启动多个子代理</td><td>Fan-out</td></tr><tr><td><code>pipeline()</code></td><td>串行执行多步流水线</td><td>Sequential</td></tr></tbody></table><p><strong>内置工作流</strong>：</p><table tabindex="0"><thead><tr><th>工作流</th><th>触发</th><th>用途</th></tr></thead><tbody><tr><td><code>/deep-research</code></td><td>斜杠命令</td><td>多轮深度调研，自动生成报告</td></tr><tr><td><code>ultracode</code></td><td>关键词</td><td>自动代码审查 + 修复流程</td></tr></tbody></table><p><strong>使用限制</strong>：</p><ul><li>Beta 阶段，API 可能变化</li><li>不支持子代理嵌套</li><li>受 <code>maxThinkingTokens</code> 限制</li><li>大小写敏感：<code>Agent()</code>、<code>AGENT()</code> 无效</li></ul><p><strong>官方文档</strong>：<a href="https://code.claude.com/docs/en/workflows" target="_blank" rel="noreferrer">Dynamic Workflows</a></p><hr><h2 id="cross-session-messaging-跨会话消息" tabindex="-1">Cross-Session Messaging（跨会话消息） <a class="header-anchor" href="#cross-session-messaging-跨会话消息" aria-label="Permalink to &quot;Cross-Session Messaging（跨会话消息）&quot;">​</a></h2><p><strong>是什么</strong>：在不同 Claude Code 会话之间发送纯文本消息，实现多会话协作。<strong>纯文本</strong>意味着不能传文件、不能传完整对话历史——这是内置的安全边界。</p><p><strong>为什么需要</strong>：多会话并行工作时（一个做后端、一个做前端），会话之间需要同步&quot;我做完了，可以接着做了&quot;这类信号，而不是要用户手动复制。</p><p><strong>核心工具</strong>：</p><table tabindex="0"><thead><tr><th>工具</th><th>用途</th></tr></thead><tbody><tr><td><code>ListAgents</code></td><td>列出当前可用的 Claude Code 会话</td></tr><tr><td><code>SendMessage</code></td><td>向指定会话发送文本消息</td></tr></tbody></table><p><strong>@mention 语法</strong>：</p><ul><li><code>@session-abc</code> — 按会话 ID 提及</li><li><code>@~/project-name</code> — 按项目路径提及</li></ul><p><strong>接收设置</strong>（完整配置参数见 <a href="./claude-code-cheatsheet.html#权限配置">cheatsheet · 权限配置</a>）：</p><table tabindex="0"><thead><tr><th>设置</th><th>可选值</th><th>说明</th></tr></thead><tbody><tr><td><code>crossSessionInbound</code></td><td>accept / hold / refuse</td><td>消息接收策略</td></tr><tr><td><code>isolatePeerMachines</code></td><td>true / false</td><td>是否隔离同网络其他机器</td></tr><tr><td><code>dialogExpiry</code></td><td>时间字符串</td><td>对话过期时间</td></tr></tbody></table><p><strong>安全规则</strong>：</p><ul><li>仅纯文本，不能发送文件或对话历史</li><li>消息只能来自已注册的会话</li><li>所有跨会话消息可审计</li></ul><p><strong>官方文档</strong>：<a href="https://code.claude.com/docs/en/cross-session-messaging" target="_blank" rel="noreferrer">Cross-Session Messaging</a></p><hr><h2 id="agent-teams-多-agent-团队-实验性" tabindex="-1">Agent Teams（多 Agent 团队，实验性） <a class="header-anchor" href="#agent-teams-多-agent-团队-实验性" aria-label="Permalink to &quot;Agent Teams（多 Agent 团队，实验性）&quot;">​</a></h2><p><strong>是什么</strong>：实验性功能，将多个 Claude Code 会话组织成团队，由 Lead 分配任务，Teammates 并行执行，共享任务列表。</p><p><strong>和 Sub-agents 的区别</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>Sub-agents</th><th>Agent Teams</th></tr></thead><tbody><tr><td>隔离级别</td><td>同终端进程内</td><td>独立会话（可 split-pane）</td></tr><tr><td>上下文</td><td>共享主代理上下文</td><td><strong>完全隔离</strong>的独立上下文</td></tr><tr><td>协调方式</td><td>主代理手动调起</td><td>共享任务列表 + Lead 分配</td></tr><tr><td>适用规模</td><td>几个并行子任务</td><td>多角色分工的复杂协作</td></tr></tbody></table><p><strong>角色</strong>：</p><table tabindex="0"><thead><tr><th>角色</th><th>职责</th></tr></thead><tbody><tr><td><strong>Lead</strong></td><td>创建任务、分配任务、审批方案、监控进度</td></tr><tr><td><strong>Teammate</strong></td><td>领取任务、执行、报告结果</td></tr></tbody></table><p><strong>队友模式</strong>：</p><table tabindex="0"><thead><tr><th>模式</th><th>说明</th></tr></thead><tbody><tr><td><strong>In-process</strong></td><td>同一终端进程内运行，共享上下文</td></tr><tr><td><strong>Split-panes</strong></td><td>独立终端（tmux/iTerm2），完全隔离</td></tr></tbody></table><p><strong>约束</strong>：</p><ul><li>无嵌套团队（一个会话一个团队）</li><li>子代理可注册为 teammate</li><li>使用 <code>CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS=1</code> 启用</li></ul><p><strong>官方文档</strong>：<a href="https://code.claude.com/docs/en/agent-teams" target="_blank" rel="noreferrer">Agent Teams</a></p><hr><h2 id="remote-control-远程控制" tabindex="-1">Remote Control（远程控制） <a class="header-anchor" href="#remote-control-远程控制" aria-label="Permalink to &quot;Remote Control（远程控制）&quot;">​</a></h2><p><strong>是什么</strong>：将 claude.ai 网页、Claude 移动 App 或 Slack 连接到本地 Claude Code 会话，实现远程交互。</p><p><strong>为什么需要</strong>：本地跑着一个长任务（编译、测试、部署），想从手机上看一眼进度、或者临时加个新指令。Remote Control 把这种&quot;远程 append&quot;做成了官方支持的能力。</p><p><strong>三种连接模式</strong>：</p><table tabindex="0"><thead><tr><th>模式</th><th>标志/命令</th><th>说明</th></tr></thead><tbody><tr><td><strong>Server</strong></td><td><code>claude --remote-control</code></td><td>持续监听远程连接</td></tr><tr><td><strong>Interactive</strong></td><td><code>/remote-control</code> 或 <code>/rc</code></td><td>临时接受一次连接</td></tr><tr><td><strong>SSH 转发</strong></td><td>SSH 隧道</td><td>远程机器通过 SSH 暴露本地端口</td></tr></tbody></table><p><strong>安全机制 — Trusted Devices</strong>：</p><ul><li>首次连接需生物识别验证（指纹/面容 ID）</li><li>信任有效期 18 小时</li><li><code>/remote-control logout</code> 立即撤销</li><li>移动端推送通知 + Presence Heartbeats（心跳检测连接活性）</li></ul><p><strong>官方文档</strong>：<a href="https://code.claude.com/docs/en/remote-control" target="_blank" rel="noreferrer">Remote Control</a></p><hr><h2 id="channels-频道" tabindex="-1">Channels（频道） <a class="header-anchor" href="#channels-频道" aria-label="Permalink to &quot;Channels（频道）&quot;">​</a></h2><p><strong>是什么</strong>：将外部消息源（Telegram、Discord、iMessage）的事件推入 Claude Code 会话，实现非 Claude 界面的任务触发。</p><p><strong>为什么需要</strong>：Remote Control 是&quot;从 Claude 界面反向控制本地会话&quot;，Channels 相反——&quot;从外部消息源（你已经在用的 Telegram/Discord/iMessage）反向触发 Claude 任务&quot;。后者更适合&quot;不是 Claude 用户但需要 Claude 帮忙&quot;的协作场景。</p><p><strong>已支持频道</strong>：</p><table tabindex="0"><thead><tr><th>频道</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Telegram</td><td>MCP 插件</td><td>从 Telegram 对话触发任务</td></tr><tr><td>Discord</td><td>MCP 插件</td><td>从 Discord channel 接收指令</td></tr><tr><td>iMessage</td><td>MCP 插件 (Bun)</td><td>从 iMessage 对话触发任务</td></tr></tbody></table><p><strong>关键特性</strong>：</p><ul><li><code>--channels</code> 标志启用</li><li>Permission relay：频道消息自动走权限流程</li><li>Sender allowlist：限制可发送者</li><li>状态：Research Preview 阶段</li></ul><p><strong>官方文档</strong>：<a href="https://code.claude.com/docs/en/channels" target="_blank" rel="noreferrer">Channels</a></p><hr><h2 id="worktree-工作树" tabindex="-1">Worktree（工作树） <a class="header-anchor" href="#worktree-工作树" aria-label="Permalink to &quot;Worktree（工作树）&quot;">​</a></h2><p><strong>是什么</strong>：利用 Git 的 <code>git worktree</code> 功能，让多个 Claude Code 会话<strong>并行工作在同一个项目的不同分支</strong>上，互不干扰。</p><p><strong>为什么需要</strong>：传统模式下，一个 Claude Code 会话占用一个工作目录。要并行做两个 feature，需要手动切分支，频繁冲突。Worktree 让每个会话有独立的目录和分支，真正并行。</p><p><strong>核心价值</strong>：</p><ul><li><strong>并行开发</strong>：一个会话做 feature A，另一个做 feature B</li><li><strong>会话隔离</strong>：每个会话有独立的工作目录和 Git 状态</li><li><strong>自动管理</strong>：Claude Code 会自动创建和清理 worktree</li></ul><p><strong>CLI 标志</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --worktree</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/claude-worktree-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><strong>隔离检查</strong>（Claude Code 启动会话前会自动验证 4 个条件）：</p><ol><li>工作目录是否在原始仓库内</li><li>Git 索引是否干净</li><li>是否有未提交的变更</li><li>是否指向正确的远程分支</li></ol><p><strong>官方文档</strong>：<a href="https://code.claude.com/docs/zh-CN/worktrees" target="_blank" rel="noreferrer">Worktree 详解</a></p><hr><h2 id="权限模式" tabindex="-1">权限模式 <a class="header-anchor" href="#权限模式" aria-label="Permalink to &quot;权限模式&quot;">​</a></h2><p><strong>是什么</strong>：控制 Claude 执行操作前要不要问你。是日常使用最高频的&quot;决策参数&quot;——选错模式，要么被确认弹窗淹没、要么失去安全边界。</p><p><strong>五种模式</strong>（完整对照表与决策指南见 <a href="./claude-code-cheatsheet.html#该用哪个权限模式">cheatsheet · 该用哪个权限模式</a>）：</p><table tabindex="0"><thead><tr><th>展示名</th><th>配置值</th><th>行为</th><th>何时使用</th></tr></thead><tbody><tr><td><strong>Normal</strong></td><td><code>default</code></td><td>执行前询问确认</td><td>默认，最谨慎</td></tr><tr><td><strong>Auto</strong></td><td><code>auto</code></td><td>AI 分类器自动决策：安全操作自动通过，危险操作拦截</td><td>推荐：无需频繁确认，又保留安全边界</td></tr><tr><td><strong>Plan</strong></td><td><code>plan</code></td><td>只读分析，不执行任何更改</td><td>先规划再行动</td></tr><tr><td><strong>Accept Edits</strong></td><td><code>acceptEdits</code></td><td>自动批准编辑类操作，命令执行等其他操作仍询问</td><td>只想放开文件编辑，命令仍需确认</td></tr><tr><td><strong>Auto-Accept</strong>（Bypass）</td><td><code>bypassPermissions</code></td><td>自动批准所有操作</td><td>完全信任 Claude 时</td></tr></tbody></table><p><strong>配置值与展示名的区别</strong>：<code>Shift+Tab</code> 循环切换的是展示名；<code>settings.json</code> 里 <code>defaultMode</code> 用的是配置值。两者一一对应，但格式不同（驼峰 vs 小写连字符）。</p><p><strong>演变趋势</strong>：从 2026 年 8 月起，Auto 模式已成为 Pro/Max/Team 计划的新默认——官方发现 AI 分类器对危险命令的识别率足够高，Normal 模式被弹窗干扰的代价比偶尔拦截低价值操作的代价高。</p><p><strong>官方文档</strong>：<a href="https://code.claude.com/docs/zh-CN/permissions" target="_blank" rel="noreferrer">权限参考</a></p><hr><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./claude-code.html">Claude Code 主教程</a> — 安装、交互、核心功能怎么用</li><li><a href="./claude-code-cheatsheet.html">Claude Code Cheatsheet</a> — 配置/决策表/数据源速查</li><li><a href="./claude-code-cookbook.html">实战工作流 Cookbook</a> — 9 大日常开发场景的提示模式</li></ul>`,152)])])}const m=s(d,[["render",n]]);export{b as __pageData,m as default};
